mapper.select:
SELECT idConsulta, idPaciente, idMedico, idCita, idDieta, fecha, pesoCapturado, tallaCapturada, imcCalculado, observaciones
FROM consulta
WHERE idConsulta = #{idConsulta}

SELECT idConsulta, idPaciente, idMedico, idCita, idDieta, fecha, pesoCapturado, tallaCapturada, imcCalculado, observaciones
FROM consulta


        AND idPaciente = #{idPaciente}


        AND idMedico = #{idMedico}


        AND fecha = #{fecha}


ORDER BY fecha DESC, idConsulta DESC
